import { useState, type FormEvent } from 'react';
import { Button, Card, Input, Stack, Text, Toast } from '@jinx-ui/react';

export default function NewsletterForm() {
  const [email, setEmail] = useState('');
  const [sentTo, setSentTo] = useState<string | null>(null);

  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) return;
    setSentTo(email);
    setEmail('');
  };

  return (
    <>
      <Card as="form" onSubmit={handleSubmit} style={{ maxWidth: 'var(--jx-size-form-md)' }}>
        <Stack direction="column" gap="var(--jx-space-4)">
          <Text as="h2" variant="heading-sm">
            Подписка на рассылку
          </Text>
          <Text variant="body-sm" color="var(--jx-color-text-muted)">
            Присылаем новости не чаще одного раза в неделю.
          </Text>
          <Input
            type="email"
            name="email"
            label="Электронная почта"
            placeholder="you@example.com"
            autoComplete="email"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            required
          />
          <Button type="submit" variant="primary" disabled={!isValid}>
            Подписаться
          </Button>
        </Stack>
      </Card>

      <Toast
        open={sentTo !== null}
        placement="bottom-end"
        status="success"
        title="Готово"
        duration={5000}
        onClose={() => setSentTo(null)}
      >
        <Text variant="body-sm">
          Письмо с подтверждением отправлено на {sentTo}.
        </Text>
      </Toast>
    </>
  );
}

